<?php
if(!defined('ABSPATH'))exit;
class Hooshid_Shortcode{
 public function __construct(){add_shortcode('hooshid',[$this,'render']);}
 public function render(){wp_enqueue_style('hooshid');wp_enqueue_script('hooshid');$books=Hooshid_Books::all();ob_start();?><div class="hooshid-app" dir="rtl"><header class="hooshid-toolbar"><strong>هوشید</strong><select class="hooshid-book"><option value="">انتخاب کتاب</option><?php foreach($books as $b):?><option value="<?php echo esc_attr($b->id);?>">پایه <?php echo esc_html($b->grade).' — '.esc_html($b->subject).' — '.esc_html($b->title);?></option><?php endforeach;?></select><input class="hooshid-page" type="number" min="1" value="1"><button class="hooshid-open-page">باز کردن</button><button data-tool="pen">قلم</button><button data-tool="eraser">پاک‌کن</button><button data-tool="line">خط</button><button data-tool="rect">مستطیل</button><button data-tool="circle">دایره</button><button data-tool="text">متن</button><button data-action="undo">↶</button><button data-action="redo">↷</button><button data-action="clear">پاک کردن</button></header><main class="hooshid-main"><section class="hooshid-board-wrap"><div class="hooshid-pdf"></div><canvas class="hooshid-canvas"></canvas><div class="hooshid-page-badge"></div></section><aside class="hooshid-chat"><h3>دستیار هوشید</h3><div class="hooshid-context"></div><div class="hooshid-messages"></div><form><textarea placeholder="مثلاً: صفحه ۱۲ ریاضی پنجم را توضیح بده"></textarea><button>ارسال</button></form></aside></main></div><?php return ob_get_clean();}
}